/* Focused layout improvements: compact facility actions and readable stage counts. */
const facilityBeforeLayoutPolish=facilityView;
facilityView=function(){const box=document.createElement('div');box.innerHTML=facilityBeforeLayoutPolish();const panel=[...box.querySelectorAll('.panel')].find(p=>p.querySelector('h2')?.textContent==='Facility actions');if(!panel)return box.innerHTML;const ribbon=document.createElement('section');ribbon.className='facility-action-ribbon';ribbon.innerHTML='<div><strong>Facility actions</strong><span>'+panel.querySelector('.insight').textContent+'</span></div>'+panel.querySelector('.actions').outerHTML;box.querySelector('.analytics-grid').before(ribbon);panel.remove();const readiness=document.createElement('section');readiness.className='panel facility-readiness';readiness.innerHTML='<div class="panelhead"><h2>Controlled-environment readiness</h2><small>Demo data</small></div>'+[['Cleanroom temperature',21.4,20,24,'°C'],['Relative humidity',46,40,55,'%'],['Differential pressure',15,10,20,'Pa']].map(([label,value,min,max,unit])=>'<button onclick="facilityDetail(0)" title="'+label+': '+value+' '+unit+' · Range '+min+'–'+max+' '+unit+'"><span>'+label+'<b>'+value+' '+unit+'</b></span><div class="readiness-range"><i style="left:'+((value-min)/(max-min)*100)+'%"></i></div><small>'+min+'–'+max+' '+unit+' <em>Within range</em></small></button>').join('');box.querySelector('.analytics-grid').appendChild(readiness);box.className='facility-polished';return '<div class="facility-polished">'+box.innerHTML+'</div>'};
